"""このファイルはブロックプログラム moon.blocks.json から自動生成されました。
ここを直接書き換えても、ブロック側には反映されません。
"""
import math
import random


def _devs(api, name, kind=None):
    if name == "*":
        return api.devices(kind)
    return api.devices(name=name)


def _val(api, name, prop, kind=None):
    ds = _devs(api, name, kind)
    if not ds:
        return 0
    d = ds[0]
    if prop == "fuel":
        return d.contents.get("fuel", 0)
    try:
        return getattr(d, prop)
    except Exception:
        return 0


def _div(a, b):
    return a / b if b else 0


def _round(a):
    # 無限大（脱出軌道の遠点など）や非数はそのまま（round では止まってしまうため）
    return round(a) if math.isfinite(a) else a


def _mod(a, b):
    return a % b if b else 0


def _sin(a):
    return math.sin(math.radians(a))


def _cos(a):
    return math.cos(math.radians(a))


def _num(a):
    try:
        return float(a)
    except (TypeError, ValueError):
        return 0.0


def _gravity(api):
    p = api.planet()
    if not p:
        return 0.0
    r2 = sum((api.position[i] - p["center"][i]) ** 2 for i in range(3))
    return p["mu"] / max(r2, 1.0)


def _pos(a):
    return a if a > 0 else 0.0


# --- 矢印（ベクトル）[x, y, z] ---
def _V(a):
    try:
        return [float(a[0]), float(a[1]), float(a[2])]
    except (TypeError, ValueError, IndexError, KeyError):
        return [0.0, 0.0, 0.0]


def _vadd(a, b):
    return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]


def _vsub(a, b):
    return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]


def _vmul(a, k):
    return [a[0] * k, a[1] * k, a[2] * k]


def _vdiv(a, k):
    return [a[0] / k, a[1] / k, a[2] / k] if k else [0.0, 0.0, 0.0]


def _vdot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def _vlen(a):
    return math.sqrt(_vdot(a, a))


def _vunit(a):
    n = _vlen(a)
    return _vmul(a, 1.0 / n) if n > 1e-9 else [0.0, 0.0, 0.0]


def _vclamp(a, n):
    k = _vlen(a)
    return _vmul(a, max(n, 0.0) / k) if k > max(n, 0.0) and k > 0 else list(a)


def _vperp(a, b):
    u = _vunit(b)
    return _vsub(a, _vmul(u, _vdot(a, u)))


def _vangle(a, b):
    na, nb = _vlen(a), _vlen(b)
    if na < 1e-9 or nb < 1e-9:
        return 0.0
    return math.degrees(math.acos(max(-1.0, min(1.0, _vdot(a, b) / (na * nb)))))


def _vtilt(a, b, deg):
    """矢印 a の向きを、b から deg 度以内にする（長さはそのまま）。"""
    n, u = _vlen(a), _vunit(b)
    if n < 1e-9 or _vlen(u) < 0.5:
        return list(a)
    d = _vmul(a, 1.0 / n)
    c, cmax = _vdot(d, u), math.cos(math.radians(max(0.0, min(180.0, deg))))
    if c >= cmax:
        return list(a)
    h = _vunit(_vsub(d, _vmul(u, c)))
    if _vlen(h) < 0.5:
        return _vmul(u, n) if deg < 90 else list(a)
    return _vmul(_vadd(_vmul(u, cmax), _vmul(h, math.sin(math.radians(deg)))), n)


def _vship(api, x, y, z):
    """船から見た (右, 上, 前) → ワールドの矢印。"""
    X, Y, Z = api.orientation()
    return [X[i] * x + Y[i] * y + Z[i] * z for i in range(3)]


def _vcomp(api, a, axis):
    if axis in "xyz":
        return a["xyz".index(axis)]
    X, Y, Z = api.orientation()
    return _vdot(a, {"r": X, "u": Y, "f": Z}[axis])


def _vget(v, name):
    x = v.get(name)
    return list(x) if isinstance(x, list) and len(x) == 3 else [0.0, 0.0, 0.0]


def _to_planet(api):
    p = api.planet()
    return _vsub(p["center"], api.position) if p else [0.0, 0.0, 0.0]


def _txt(a):
    if isinstance(a, list):
        return "(" + ", ".join("%.1f" % x for x in a) + ")"
    return str(a)


def _radio(api, ch):
    v = api.latest(str(ch))
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0



def tick(api):
    m = api.memory
    if api.time - m.get('_last', -99.0) > 0.5:   # 起動し直したら最初から
        m.clear()
    m['_last'] = api.time
    v = m.setdefault('vars', {})
    first = '_t0' not in m
    if first:
        m['_t0'] = api.time
        m['_timer'] = api.time
    keys = api.input
    prev = set(m.get('_keys', []))
    m['_keys'] = sorted(keys)
    # --- 起動したとき ---
    if first:
        v['段階'] = 0
        v['時刻0'] = api.time
    # --- ずっと（0.05秒ごと） ---
    if ((v.get('段階', 0) < 2) and (not bool(api.seated))):
        v['段階'] = 0
        v['時刻0'] = api.time
    v['推力'] = 1200000
    if bool(_val(api, 'ブースターの留め具 前', 'attached')):
        v['推力'] = _num(v.get('推力', 0)) + 300000
    if bool(_val(api, 'ブースターの留め具 後', 'attached')):
        v['推力'] = _num(v.get('推力', 0)) + 300000
    if (bool(_val(api, 'ブースターの留め具 前', 'attached')) and (_val(api, 'ブースター前のタンク', 'fuel') < 8)):
        for d in _devs(api, 'ブースターの留め具 前', 'actuator'):
            d.detach()
        for d in _devs(api, 'ブースターの留め具 後', 'actuator'):
            d.detach()
        print('ブースターを切り離しました（第1段 → 第2段）')
    v['最大加速'] = _div(v.get('推力', 0), api.mass)
    v['発着場へ'] = _vsub([0, 157.341, 3969.01], _V(api.position))
    v['高さ'] = (_vdot(_vget(v, '発着場へ'), [0, 0.999, -0.053]) * -1)
    v['行きたい速度'] = [0, 0, 0]
    if (v.get('段階', 0) == 0):
        if bool(api.seated):
            v['段階'] = 1
    if (v.get('段階', 0) == 1):
        v['残り'] = (3 - (api.time - v.get('時刻0', 0)))
        if (v.get('残り', 0) < 0.001):
            v['段階'] = 2
            for d in _devs(api, '給油口', 'actuator'):
                d.detach()
            print('給油口を切り離しました。発進！')
    if (v.get('段階', 0) == 2):
        v['行きたい速度'] = _vmul(_V(api.up), 18)
        if (api.altitude > 35):
            v['段階'] = 3
            print('巡航：月へ')
    if (v.get('段階', 0) == 3):
        v['ずれ'] = _vsub([0, 247.212, 3964.2], _V(api.position))
        v['距離'] = _vlen(_vget(v, 'ずれ'))
        v['巡航の速さ'] = math.sqrt((5 * v.get('距離', 0)))
        if (v.get('巡航の速さ', 0) > 70):
            v['巡航の速さ'] = 70
        v['行きたい速度'] = _vmul(_vunit(_vget(v, 'ずれ')), v.get('巡航の速さ', 0))
        if ((v.get('距離', 0) < 6) and (api.speed < 4)):
            v['段階'] = 4
            print('降下')
    if (v.get('段階', 0) == 4):
        v['横のずれ'] = _vperp(_vget(v, '発着場へ'), [0, 0.999, -0.053])
        v['降りる速さ'] = ((v.get('高さ', 0) - 1.5) * 0.2)
        if (v.get('降りる速さ', 0) > 4):
            v['降りる速さ'] = 4
        if (v.get('降りる速さ', 0) < 0.6):
            v['降りる速さ'] = 0.6
        v['許すずれ'] = (v.get('高さ', 0) * 0.15)
        if (v.get('許すずれ', 0) < 1):
            v['許すずれ'] = 1
        if (_vlen(_vget(v, '横のずれ')) > v.get('許すずれ', 0)):
            v['降りる速さ'] = 0
        v['行きたい速度'] = _vadd(_vmul([0, 0.999, -0.053], (v.get('降りる速さ', 0) * -1)), _vclamp(_vmul(_vget(v, '横のずれ'), 0.35), 3))
        if ((v.get('高さ', 0) < 1.5) and (api.speed < 1.2)):
            v['段階'] = 5
            print('着陸しました！ ようこそルナ・ポートへ')
    if ((v.get('段階', 0) == 0) or (v.get('段階', 0) == 5)):
        for d in _devs(api, '*', 'valve'):
            d.open = max(0.0, min(1.0, 0))
    else:
        v['重力'] = _V(api.gravity)
        v['加速'] = _vsub(_vmul(_vsub(_vget(v, '行きたい速度'), _V(api.velocity)), 0.8), _vget(v, '重力'))
        if (v.get('段階', 0) == 1):
            v['加速'] = [0, 0, 0]
        v['出力'] = _div(_vlen(_vget(v, '加速')), v.get('最大加速', 0))
